import{_ as t,o as a,c as i,l as s,t as o,N as n}from"./chunks/framework.CMqbtke2.js";const g=JSON.parse('{"title":"gitprotocol-capabilities | x-cmd man (git man5) | Protocol v0 and v1 capabilities","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitprotocol-capabilities - Protocol v0 and v1 capabilities","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitprotocol-capabilities | x-cmd man (git man5) | Protocol v0 and v1 capabilities"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitprotocol-capabilities - Protocol v0 and v1 capabilities"}]]},"headers":[],"params":{"isMan":true,"man":"gitprotocol-capabilities","category":"git man5","desc":"Protocol v0 and v1 capabilities"},"relativePath":"git/man5/gitprotocol-capabilities.md","filePath":"git/man5/gitprotocol-capabilities.md"}'),r={name:"git/man5/gitprotocol-capabilities.md"},h={class:"visually-hidden"},l=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitprotocol-capabilities - Protocol v0 and v1 capabilities</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">over-the-wire-protocol</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; this document describes capabilities for versions 0 and 1 of the pack protocol. For version 2, please refer to the <strong>gitprotocol-v2</strong>(5) doc.</p></blockquote><p>Servers SHOULD support all capabilities defined in this document.</p><p>On the very first line of the initial server response of either receive-pack and upload-pack the first reference is followed by a NUL byte and then a list of space delimited server capabilities. These allow the server to declare what it can and cannot support to the client.</p><p>Client will then send a space separated list of capabilities it wants to be in effect. The client MUST NOT ask for capabilities the server did not say it supports.</p><p>Server MUST diagnose and abort if capabilities it does not understand was sent. Server MUST NOT ignore capabilities that client requested and server advertised. As a consequence of these rules, server MUST NOT advertise capabilities it does not understand.</p><p>The <em>atomic</em>, <em>report-status</em>, <em>report-status-v2</em>, <em>delete-refs</em>, <em>quiet</em>, and <em>push-cert</em> capabilities are sent and recognized by the receive-pack (push to server) process.</p><p>The <em>ofs-delta</em> and <em>side-band-64k</em> capabilities are sent and recognized by both upload-pack and receive-pack protocols. The <em>agent</em> and <em>session-id</em> capabilities may optionally be sent in both protocols.</p><p>All other capabilities are only recognized by the upload-pack (fetch from server) process.</p><h2 id="multi-ack" tabindex="-1">MULTI_ACK <a class="header-anchor" href="#multi-ack" aria-label="Permalink to &quot;MULTI_ACK&quot;">​</a></h2><p>The <em>multi_ack</em> capability allows the server to return &quot;ACK obj-id continue&quot; as soon as it finds a commit that it can use as a common base, between the client&#39;s wants and the client&#39;s have set.</p><p>By sending this early, the server can potentially head off the client from walking any further down that particular branch of the client&#39;s repository history. The client may still need to walk down other branches, sending have lines for those, until the server has a complete cut across the DAG, or the client has said &quot;done&quot;.</p><p>Without multi_ack, a client sends have lines in --date-order until the server has found a common base. That means the client will send have lines that are already known by the server to be common, because they overlap in time with another branch that the server hasn&#39;t found a common base on yet.</p><p>For example suppose the client has commits in caps that the server doesn&#39;t and the server has commits in lower case that the client doesn&#39;t, as in the following diagram:</p><blockquote><pre><code>      +---- u ---------------------- x
     /              +----- y
    /              /
   a -- b -- c -- d -- E -- F
       &lt;br&gt; &gt;     +--- Q -- R -- S
</code></pre></blockquote><p>If the client wants x,y and starts out by saying have F,S, the server doesn&#39;t know what F,S is. Eventually the client says &quot;have d&quot; and the server sends &quot;ACK d continue&quot; to let the client know to stop walking down that line (so don&#39;t send c-b-a), but it&#39;s not done yet, it needs a base for x. The client keeps going with S-R-Q, until a gets reached, at which point the server has a clear base and it all ends.</p><p>Without multi_ack the client would have sent that c-b-a chain anyway, interleaved with S-R-Q.</p><h2 id="multi-ack-detailed" tabindex="-1">MULTI_ACK_DETAILED <a class="header-anchor" href="#multi-ack-detailed" aria-label="Permalink to &quot;MULTI_ACK_DETAILED&quot;">​</a></h2><p>This is an extension of multi_ack that permits client to better understand the server&#39;s in-memory state. See <strong>gitprotocol-pack</strong>(5), section &quot;Packfile Negotiation&quot; for more information.</p><h2 id="no-done" tabindex="-1">NO-DONE <a class="header-anchor" href="#no-done" aria-label="Permalink to &quot;NO-DONE&quot;">​</a></h2><p>This capability should only be used with the smart HTTP protocol. If multi_ack_detailed and no-done are both present, then the sender is free to immediately send a pack following its first &quot;ACK obj-id ready&quot; message.</p><p>Without no-done in the smart HTTP protocol, the server session would end and the client has to make another trip to send &quot;done&quot; before the server can send the pack. no-done removes the last round and thus slightly reduces latency.</p><h2 id="thin-pack" tabindex="-1">THIN-PACK <a class="header-anchor" href="#thin-pack" aria-label="Permalink to &quot;THIN-PACK&quot;">​</a></h2><p>A thin pack is one with deltas which reference base objects not contained within the pack (but are known to exist at the receiving end). This can reduce the network traffic significantly, but it requires the receiving end to know how to &quot;thicken&quot; these packs by adding the missing bases to the pack.</p><p>The upload-pack server advertises <em>thin-pack</em> when it can generate and send a thin pack. A client requests the <em>thin-pack</em> capability when it understands how to &quot;thicken&quot; it, notifying the server that it can receive such a pack. A client MUST NOT request the <em>thin-pack</em> capability if it cannot turn a thin pack into a self-contained pack.</p><p>Receive-pack, on the other hand, is assumed by default to be able to handle thin packs, but can ask the client not to use the feature by advertising the <em>no-thin</em> capability. A client MUST NOT send a thin pack if the server advertises the <em>no-thin</em> capability.</p><p>The reasons for this asymmetry are historical. The receive-pack program did not exist until after the invention of thin packs, so historically the reference implementation of receive-pack always understood thin packs. Adding <em>no-thin</em> later allowed receive-pack to disable the feature in a backwards-compatible manner.</p><h2 id="side-band-side-band-64k" tabindex="-1">SIDE-BAND, SIDE-BAND-64K <a class="header-anchor" href="#side-band-side-band-64k" aria-label="Permalink to &quot;SIDE-BAND, SIDE-BAND-64K&quot;">​</a></h2><p>This capability means that server can send, and client understand multiplexed progress reports and error info interleaved with the packfile itself.</p><p>These two options are mutually exclusive. A modern client always favors <em>side-band-64k</em>.</p><p>Either mode indicates that the packfile data will be streamed broken up into packets of up to either 1000 bytes in the case of <em>side_band</em>, or 65520 bytes in the case of <em>side_band_64k</em>. Each packet is made up of a leading 4-byte pkt-line length of how much data is in the packet, followed by a 1-byte stream code, followed by the actual data.</p><p>The stream code can be one of:</p><blockquote><pre><code>1 - pack data
2 - progress messages
3 - fatal error message just before stream aborts
</code></pre></blockquote><p>The &quot;side-band-64k&quot; capability came about as a way for newer clients that can handle much larger packets to request packets that are actually crammed nearly full, while maintaining backward compatibility for the older clients.</p><p>Further, with side-band and its up to 1000-byte messages, it&#39;s actually 999 bytes of payload and 1 byte for the stream code. With side-band-64k, same deal, you have up to 65519 bytes of data and 1 byte for the stream code.</p><p>The client MUST send only maximum of one of &quot;side-band&quot; and &quot;side- band-64k&quot;. Server MUST diagnose it as an error if client requests both.</p><h2 id="ofs-delta" tabindex="-1">OFS-DELTA <a class="header-anchor" href="#ofs-delta" aria-label="Permalink to &quot;OFS-DELTA&quot;">​</a></h2><p>Server can send, and client understand PACKv2 with delta referring to its base by position in pack rather than by an obj-id. That is, they can send/read OBJ_OFS_DELTA (aka type 6) in a packfile.</p><h2 id="agent" tabindex="-1">AGENT <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;AGENT&quot;">​</a></h2><p>The server may optionally send a capability of the form <strong>agent=X</strong> to notify the client that the server is running version <strong>X</strong>. The client may optionally return its own agent string by responding with an <strong>agent=Y</strong> capability (but it MUST NOT do so if the server did not mention the agent capability). The <strong>X</strong> and <strong>Y</strong> strings may contain any printable ASCII characters except space (i.e., the byte range 32 &lt; x &lt; 127), and are typically of the form &quot;package/version&quot; (e.g., &quot;git/1.8.3.1&quot;). The agent strings are purely informative for statistics and debugging purposes, and MUST NOT be used to programmatically assume the presence or absence of particular features.</p><h2 id="object-format" tabindex="-1">OBJECT-FORMAT <a class="header-anchor" href="#object-format" aria-label="Permalink to &quot;OBJECT-FORMAT&quot;">​</a></h2><p>This capability, which takes a hash algorithm as an argument, indicates that the server supports the given hash algorithms. It may be sent multiple times; if so, the first one given is the one used in the ref advertisement.</p><p>When provided by the client, this indicates that it intends to use the given hash algorithm to communicate. The algorithm provided must be one that the server supports.</p><p>If this capability is not provided, it is assumed that the only supported algorithm is SHA-1.</p><h2 id="symref" tabindex="-1">SYMREF <a class="header-anchor" href="#symref" aria-label="Permalink to &quot;SYMREF&quot;">​</a></h2><p>This parameterized capability is used to inform the receiver which symbolic ref points to which ref; for example, &quot;symref=HEAD:refs/heads/master&quot; tells the receiver that HEAD points to master. This capability can be repeated to represent multiple symrefs.</p><p>Servers SHOULD include this capability for the HEAD symref if it is one of the refs being sent.</p><p>Clients MAY use the parameters from this capability to select the proper initial branch when cloning a repository.</p><h2 id="shallow" tabindex="-1">SHALLOW <a class="header-anchor" href="#shallow" aria-label="Permalink to &quot;SHALLOW&quot;">​</a></h2><p>This capability adds &quot;deepen&quot;, &quot;shallow&quot; and &quot;unshallow&quot; commands to the fetch-pack/upload-pack protocol so clients can request shallow clones.</p><h2 id="deepen-since" tabindex="-1">DEEPEN-SINCE <a class="header-anchor" href="#deepen-since" aria-label="Permalink to &quot;DEEPEN-SINCE&quot;">​</a></h2><p>This capability adds &quot;deepen-since&quot; command to fetch-pack/upload-pack protocol so the client can request shallow clones that are cut at a specific time, instead of depth. Internally it&#39;s equivalent of doing &quot;rev-list --max-age=&lt;timestamp&gt;&quot; on the server side. &quot;deepen-since&quot; cannot be used with &quot;deepen&quot;.</p><h2 id="deepen-not" tabindex="-1">DEEPEN-NOT <a class="header-anchor" href="#deepen-not" aria-label="Permalink to &quot;DEEPEN-NOT&quot;">​</a></h2><p>This capability adds &quot;deepen-not&quot; command to fetch-pack/upload-pack protocol so the client can request shallow clones that are cut at a specific revision, instead of depth. Internally it&#39;s equivalent of doing &quot;rev-list --not &lt;rev&gt;&quot; on the server side. &quot;deepen-not&quot; cannot be used with &quot;deepen&quot;, but can be used with &quot;deepen-since&quot;.</p><h2 id="deepen-relative" tabindex="-1">DEEPEN-RELATIVE <a class="header-anchor" href="#deepen-relative" aria-label="Permalink to &quot;DEEPEN-RELATIVE&quot;">​</a></h2><p>If this capability is requested by the client, the semantics of &quot;deepen&quot; command is changed. The &quot;depth&quot; argument is the depth from the current shallow boundary, instead of the depth from remote refs.</p><h2 id="no-progress" tabindex="-1">NO-PROGRESS <a class="header-anchor" href="#no-progress" aria-label="Permalink to &quot;NO-PROGRESS&quot;">​</a></h2><p>The client was started with &quot;git clone -q&quot; or something, and doesn&#39;t want that side band 2. Basically the client just says &quot;I do not wish to receive stream 2 on sideband, so do not send it to me, and if you did, I will drop it on the floor anyway&quot;. However, the sideband channel 3 is still used for error responses.</p><h2 id="include-tag" tabindex="-1">INCLUDE-TAG <a class="header-anchor" href="#include-tag" aria-label="Permalink to &quot;INCLUDE-TAG&quot;">​</a></h2><p>The <em>include-tag</em> capability is about sending annotated tags if we are sending objects they point to. If we pack an object to the client, and a tag object points exactly at that object, we pack the tag object too. In general this allows a client to get all new annotated tags when it fetches a branch, in a single network connection.</p><p>Clients MAY always send include-tag, hardcoding it into a request when the server advertises this capability. The decision for a client to request include-tag only has to do with the client&#39;s desires for tag data, whether or not a server had advertised objects in the refs/tags/* namespace.</p><p>Servers MUST pack the tags if their referrant is packed and the client has requested include-tags.</p><p>Clients MUST be prepared for the case where a server has ignored include-tag and has not actually sent tags in the pack. In such cases the client SHOULD issue a subsequent fetch to acquire the tags that include-tag would have otherwise given the client.</p><p>The server SHOULD send include-tag, if it supports it, regardless of whether or not there are tags available.</p><h2 id="report-status" tabindex="-1">REPORT-STATUS <a class="header-anchor" href="#report-status" aria-label="Permalink to &quot;REPORT-STATUS&quot;">​</a></h2><p>The receive-pack process can receive a <em>report-status</em> capability, which tells it that the client wants a report of what happened after a packfile upload and reference update. If the pushing client requests this capability, after unpacking and updating references the server will respond with whether the packfile unpacked successfully and if each reference was updated successfully. If any of those were not successful, it will send back an error message. See <strong>gitprotocol-pack</strong>(5) for example messages.</p><h2 id="report-status-v2" tabindex="-1">REPORT-STATUS-V2 <a class="header-anchor" href="#report-status-v2" aria-label="Permalink to &quot;REPORT-STATUS-V2&quot;">​</a></h2><p>Capability <em>report-status-v2</em> extends capability <em>report-status</em> by adding new &quot;option&quot; directives in order to support reference rewritten by the &quot;proc-receive&quot; hook. The &quot;proc-receive&quot; hook may handle a command for a pseudo-reference which may create or update a reference with different name, new-oid, and old-oid. While the capability <em>report-status</em> cannot report for such case. See <strong>gitprotocol-pack</strong>(5) for details.</p><h2 id="delete-refs" tabindex="-1">DELETE-REFS <a class="header-anchor" href="#delete-refs" aria-label="Permalink to &quot;DELETE-REFS&quot;">​</a></h2><p>If the server sends back the <em>delete-refs</em> capability, it means that it is capable of accepting a zero-id value as the target value of a reference update. It is not sent back by the client, it simply informs the client that it can be sent zero-id values to delete references.</p><h2 id="quiet" tabindex="-1">QUIET <a class="header-anchor" href="#quiet" aria-label="Permalink to &quot;QUIET&quot;">​</a></h2><p>If the receive-pack server advertises the <em>quiet</em> capability, it is capable of silencing human-readable progress output which otherwise may be shown when processing the received pack. A send-pack client should respond with the <em>quiet</em> capability to suppress server-side progress reporting if the local progress reporting is also being suppressed (e.g., via <strong>push -q</strong>, or if stderr does not go to a tty).</p><h2 id="atomic" tabindex="-1">ATOMIC <a class="header-anchor" href="#atomic" aria-label="Permalink to &quot;ATOMIC&quot;">​</a></h2><p>If the server sends the <em>atomic</em> capability it is capable of accepting atomic pushes. If the pushing client requests this capability, the server will update the refs in one atomic transaction. Either all refs are updated or none.</p><h2 id="push-options" tabindex="-1">PUSH-OPTIONS <a class="header-anchor" href="#push-options" aria-label="Permalink to &quot;PUSH-OPTIONS&quot;">​</a></h2><p>If the server sends the <em>push-options</em> capability it is able to accept push options after the update commands have been sent, but before the packfile is streamed. If the pushing client requests this capability, the server will pass the options to the pre- and post- receive hooks that process this push request.</p><h2 id="allow-tip-sha1-in-want" tabindex="-1">ALLOW-TIP-SHA1-IN-WANT <a class="header-anchor" href="#allow-tip-sha1-in-want" aria-label="Permalink to &quot;ALLOW-TIP-SHA1-IN-WANT&quot;">​</a></h2><p>If the upload-pack server advertises this capability, fetch-pack may send &quot;want&quot; lines with object names that exist at the server but are not advertised by upload-pack. For historical reasons, the name of this capability contains &quot;sha1&quot;. Object names are always given using the object format negotiated through the <em>object-format</em> capability.</p><h2 id="allow-reachable-sha1-in-want" tabindex="-1">ALLOW-REACHABLE-SHA1-IN-WANT <a class="header-anchor" href="#allow-reachable-sha1-in-want" aria-label="Permalink to &quot;ALLOW-REACHABLE-SHA1-IN-WANT&quot;">​</a></h2><p>If the upload-pack server advertises this capability, fetch-pack may send &quot;want&quot; lines with object names that exist at the server but are not advertised by upload-pack. For historical reasons, the name of this capability contains &quot;sha1&quot;. Object names are always given using the object format negotiated through the <em>object-format</em> capability.</p><h2 id="push-cert-nonce" tabindex="-1">PUSH-CERT=&lt;NONCE&gt; <a class="header-anchor" href="#push-cert-nonce" aria-label="Permalink to &quot;PUSH-CERT=\\&lt;NONCE\\&gt;&quot;">​</a></h2><p>The receive-pack server that advertises this capability is willing to accept a signed push certificate, and asks the &lt;nonce&gt; to be included in the push certificate. A send-pack client MUST NOT send a push-cert packet unless the receive-pack server advertises this capability.</p><h2 id="filter" tabindex="-1">FILTER <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;FILTER&quot;">​</a></h2><p>If the upload-pack server advertises the <em>filter</em> capability, fetch-pack may send &quot;filter&quot; commands to request a partial clone or partial fetch and request that the server omit various objects from the packfile.</p><h2 id="session-id-session-id" tabindex="-1">SESSION-ID=&lt;SESSION ID&gt; <a class="header-anchor" href="#session-id-session-id" aria-label="Permalink to &quot;SESSION-ID=\\&lt;SESSION ID\\&gt;&quot;">​</a></h2><p>The server may advertise a session ID that can be used to identify this process across multiple requests. The client may advertise its own session ID back to the server as well.</p><p>Session IDs should be unique to a given process. They must fit within a packet-line, and must not contain non-printable or whitespace characters. The current implementation uses trace2 session IDs (see <strong>api-trace2</strong>[1] for details), but this may change and users of the session ID should not rely on this fact.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: api-trace2</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file:///usr/share/doc/git/technical/api-trace2.html</span></span></code></pre></div>`,97);function c(e,d,p,u,m,b){return a(),i("div",null,[s("h1",h,o(e.$params.man),1),l])}const y=t(r,[["render",c]]);export{g as __pageData,y as default};
